import java.util.HashMap;
import java.util.Map;

public class Solution {
    // O(n): para cada x, quantos complementos (k - x) já apareceram antes.
    static long contarPares(int[] nums, int k) {
        Map<Long, Long> vistos = new HashMap<>();
        long pares = 0;
        for (int x : nums) {
            long complemento = (long) k - x;
            pares += vistos.getOrDefault(complemento, 0L);
            vistos.merge((long) x, 1L, Long::sum);
        }
        return pares;
    }
}

