import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplos() {
        assertEquals(2, Solution.contarPares(new int[]{1, 5, 3, 3, 7}, 6));
        assertEquals(3, Solution.contarPares(new int[]{2, 2, 2}, 4));
    }

    @Test void semPares() {
        assertEquals(0, Solution.contarPares(new int[]{}, 1));
        assertEquals(0, Solution.contarPares(new int[]{1, 2, 3}, 100));
    }

    @Test void somaQueEstouraInt() {
        assertEquals(1, Solution.contarPares(new int[]{Integer.MAX_VALUE, -1, 0}, Integer.MAX_VALUE - 1));
    }

    @Test void grandeComResultadoLong() {
        int[] nums = new int[100_000];
        java.util.Arrays.fill(nums, 7);
        assertEquals(100_000L * 99_999 / 2, Solution.contarPares(nums, 14));
    }
}
